<?php require __DIR__.'/../app/bootstrap.php';$u=role(['admin','kasir']);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare("INSERT INTO payments(ticket_id,amount,method,received_by)VALUES(?,?,?,?)");$s->execute([(int)$_POST['ticket_id'],max(0,(float)$_POST['amount']),in_array($_POST['method'],['cash','transfer','qris','other'],true)?$_POST['method']:'other',$u['id']]);audit($pdo,$u['id'],'payment_create','ticket='.$_POST['ticket_id']);header('Location:payments.php');exit;}$rows=$pdo->query("SELECT t.id,t.ticket_no,t.final_cost,c.name,COALESCE((SELECT SUM(amount) FROM payments p WHERE p.ticket_id=t.id),0) paid FROM tickets t JOIN customers c ON c.id=t.customer_id ORDER BY t.id DESC LIMIT 100")->fetchAll();?><!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Pembayaran</title><style>body{font:14px Arial;background:#f5f7fb;margin:0}.top{background:#111827;color:#fff;padding:16px 24px}.top a{color:#fff;margin-left:14px}.wrap{max-width:1100px;margin:25px auto;padding:0 15px}.card{background:#fff;padding:18px;border-radius:12px;margin-bottom:15px}.form{display:flex;gap:8px;flex-wrap:wrap}.input{padding:9px}.btn{background:#2563eb;color:#fff;border:0;padding:10px;border-radius:7px}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}</style><div class=top><b>🔧 ServisPro</b><a href=index.php>Dashboard</a><a href=tickets.php>Tiket</a><a href=customers.php>Pelanggan</a><a href=parts.php>Sparepart</a><a href=logout.php>Keluar</a></div><div class=wrap><h2>Pembayaran</h2><div class=card><form method=post class=form><input type=hidden name=csrf value="<?=e(csrf())?>"><input class=input type=number name=ticket_id placeholder="ID database tiket" required><input class=input type=number name=amount min=0 placeholder=Jumlah required><select class=input name=method><option>cash</option><option>transfer</option><option>qris</option><option>other</option></select><button class=btn>Catat</button></form></div><div class=card><table><tr><th>Tiket</th><th>Pelanggan</th><th>Total</th><th>Dibayar</th><th>Sisa</th></tr><?php foreach($rows as $r):$s=max(0,$r['final_cost']-$r['paid']);?><tr><td><?=e($r['ticket_no'])?></td><td><?=e($r['name'])?></td><td>Rp<?=number_format($r['final_cost'],0,',','.')?></td><td>Rp<?=number_format($r['paid'],0,',','.')?></td><td>Rp<?=number_format($s,0,',','.')?></td></tr><?php endforeach;?></table></div></div>